app.add_middleware(GZipMiddleware, minimum_size=900, compresslevel=5)

PREDICTION_ENGINE_VERSION = "kraiz-edge-2026.09-v11"
VOLATILITY_ENGINE_VERSION = "kraiz-volatility-v1"


@app.middleware("http")
async def _kraiz_timing(request: Request, call_next):
    started=time.perf_counter()
    response=await call_next(request)
    try:response.headers["X-KRAIZ-ms"]=f"{(time.perf_counter()-started)*1000:.1f}"
    except Exception:pass
    return response

