CSS += r"""
/* v124: true fixed home hero.
   sticky was unreliable in iOS/PWA scrolling; fixed is deliberate here. */
.smart-home .smart-home-hero{
  position:fixed!important;
  top:0!important;
  left:0!important;
  right:0!important;
  width:min(920px,100%)!important;
  max-width:920px!important;
  margin:0 auto!important;
  z-index:120!important;
  box-shadow:0 10px 28px rgba(0,0,0,.32)!important;
}
.smart-home .smart-home-main{
  position:relative;
  z-index:1;
  padding-top:260px!important;
}
@media(max-width:560px){
  .smart-home .smart-home-main{
    padding-top:220px!important;
  }
}
html.pwa-standalone .smart-home .smart-home-hero{
  top:env(safe-area-inset-top)!important;
}
html.pwa-standalone .smart-home .smart-home-main{
  padding-top:calc(260px + env(safe-area-inset-top))!important;
}
@media(max-width:560px){
  html.pwa-standalone .smart-home .smart-home-main{
    padding-top:calc(220px + env(safe-area-inset-top))!important;
  }
}
"""


